using UnityEngine;
public class TallGrass : MonoBehaviour
{
	public Sprite[] spriteVars;
	public Sprite[] cutSprites;
	private static Vector3 cutOffset = new Vector3(0f, 0.5f, 0f);
	private SpriteRenderer spriteRenderer;
	private Vector3 cutPosition;
	private int spriteIndex;
	public void Awake()
	{
		Health component = GetComponent<Health>();
		component.takeDamageEnterHandlers = (Health.OnTakeDamageHandler)Delegate.Combine(component.takeDamageEnterHandlers, new Health.OnTakeDamageHandler(CutGrass));
		spriteRenderer = transform.Find("GrassSprite").GetComponent<SpriteRenderer>();
		spriteIndex = UnityEngine.Random.Range(0, spriteVars.Length);
		spriteRenderer.sprite = spriteVars[spriteIndex];
	}
	public void CutGrass(AttackInfo givenInfo, Entity givenEnt = null)
	{
		cutPosition = transform.position + cutOffset;
		SoundManager.PlayAudioWithDistance("GrassCut", cutPosition);
		PoolManager.GetPoolItem<ParticleEffect>("TallGrassEmitter").Emit(5, cutPosition);
		spriteRenderer.sprite = cutSprites[spriteIndex];
		spriteRenderer.sortingLayerName = "FloorDoodad";
		spriteRenderer.transform.SetParent(transform.parent);
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}
}
