	public AutoTiler(int[] tileSetIDs = null, string[] tileLayerNames = null, int[] tileSetIDWeights = null, bool markAsDoodad = false, bool markAsObstacle = false, GridTestGroup<TileGrid, Tile> testGroup = null, string tileLayerName = "", bool markAsEnemy = false, string tileSetName = "", bool flipX = false, bool flipY = false, float flipXChance = 1f, float flipYChance = 1f, Tile.TerrainType? terrain = null)
	{
		this.tileSetIDs = tileSetIDs;
		if (tileSetIDs == null)
		{
			this.tileSetIDs = new int[0];
		}
		this.tileLayerNames = tileLayerNames;
		if (tileLayerNames == null)
		{
			this.tileLayerNames = new string[0];
		}
		this.markAsDoodad = markAsDoodad;
		this.markAsObstacle = markAsObstacle;
		this.markAsEnemy = markAsEnemy;
		this.flipX = flipX;
		this.flipY = flipY;
		this.flipXChance = flipXChance;
		this.flipYChance = flipYChance;
		this.tileSetName = tileSetName;
		this.testGroup = testGroup;
		if (testGroup == null)
		{
			this.testGroup = new GridTestGroup<TileGrid, Tile>();
		}
		if (tileLayerName != string.Empty && this.tileLayerNames.Length == 0)
		{
			this.tileLayerNames = new string[1] { tileLayerName };
		}
		if (terrain.HasValue)
		{
			this.terrain = terrain.Value;
		}
	}
	public void Apply(TileGrid tileGrid, int row, int col, int rowOffset = 0, int colOffset = 0, int rowCount = 0, int colCount = 0)
	{
		if (!testGroup.Test(tileGrid, row, col, rowOffset, colOffset, rowCount, colCount))
		{
			return;
		}
		Tile tile = tileGrid[row, col];
		if (markAsEnemy)
		{
			tile.hasEnemy = true;
		}
		if (markAsObstacle)
		{
			tile.obstacle = true;
		}
		Tile.TerrainType? terrainType = terrain;
		if (terrainType.HasValue)
		{
			Tile.TerrainType? terrainType2 = terrain;
			tile.terrain = terrainType2.Value;
		}
		for (int i = 0; i < tileLayerNames.Length; i++)
		{
			if (tileSetIDs != null && tileSetIDs.Length > 0)
			{
				tile.layers[tileLayerNames[i]].tileSetID = tileSetIDs.GetRandomValue();
				if (tileSetName != string.Empty)
				{
					tile.layers[tileLayerNames[i]].tileSetName = tileSetName;
				}
			}
			tile.layers[tileLayerNames[i]].flipX = flipX;
			tile.layers[tileLayerNames[i]].flipY = flipY;
			if (flipX && flipXChance <= 1f && Random.value > flipXChance)
			{
				tile.layers[tileLayerNames[i]].flipX = !flipX;
			}
			if (flipY && flipYChance <= 1f && Random.value > flipYChance)
			{
				tile.layers[tileLayerNames[i]].flipY = !flipY;
			}
			if (markAsDoodad)
			{
				tile.layers[tileLayerNames[i]].hasDoodad = true;
			}
		}
	}
