		{
			return;
		}
		spawnOrigins.Add(new IntVec2(rowOrigin, colOrigin));
		RecordGlobalPosition(tileGrid, rowOrigin, colOrigin, parentTrans, room, isOrigin: true);
		for (int i = 0; i < RowCount; i++)
		{
			for (int j = 0; j < ColCount; j++)
			{
				IntVec2 directionalRowCol = Globals.GetDirectionalRowCol(rowOrigin, colOrigin, direction, i, j);
				int x = directionalRowCol.x;
				int y = directionalRowCol.y;
				spawnPositions.Add(new IntVec2(x, y));
				RecordGlobalPosition(tileGrid, x, y, parentTrans, room);
				if (curGridDecoGroup != null)
				{
					for (int k = 0; k < curGridDecoGroup.Count; k++)
					{
						if (tileGrid.InBounds(x, y))
						{
							curGridDecoGroup[k].Apply(tileGrid, x, y, i, j, direction, prefabRowOffset, prefabColOffset);
						}
					}
				}
				int colOffset = j;
				int rowOffset = i;
				for (int l = 0; l < autoTilers.Count; l++)
