    d["confidence"] = conf
    return d


def N(value, unit=None, note=None):
    d = {"value": value}
    if unit:
        d["unit"] = unit
    if note:
        d["note"] = note
    return d


def build(path, goal, rules, open_questions, acceptance):
    with open(path, encoding="utf-8") as f:
